function initColorbox() {
  $('.contact-link').colorbox({
    opacity: .7,
    href: function() {
      return $(this).attr('href') + ' #main';
    },
    onComplete: function() {
      $('#webform-component-company label').append('<span class="form-required">*</span>');
      $('#webform-component-application > .form-item > label').append('<span class="form-required">*</span>');
      $("#edit-submitted-company").attr('disabled', 'disabled');
      $("#webform-component-company").hide();
      $("#edit-submitted-application").attr('disabled', 'disabled');
      $("#webform-component-application").hide();
      $("#webform-component-are-you-working-with").hide();
      $("#webform-component-name-of-company-you-are-working-with").hide();
     $("#webform-client-form-20").validate({
       rules: {
         "submitted[first_name]": "required",
         "submitted[last_name]": "required",
         "submitted[email_address]":  {
            required: true,
            email: true
          },
         "submitted[what_best_desribes_you]": "required"
       },
       errorPlacement: function(error, element) {
         element.after(error);
       }, 
       submitHandler: function(form) {
         $(form).ajaxSubmit({ 
           success: function(responseText, statusText) {
             $('#cboxLoadedContent #contact-body').html( $('#main', responseText) );
           }
         });
       }
     });
      $('#webform-client-form-20 #edit-submitted-what-best-describes-you').change(function() {
        //bind to the change event to show/hide company and/or application fields
        var myVal = $(this).val();
        switch(myVal) {
          case 'Consumer':
            $('#webform-component-company').hide();
            $('#edit-submitted-company').rules("remove");
            $('#webform-component-application').hide();
            $('#webform-component-are-you-working-with').hide();
            $('#webform-component-name-of-company-you-are-working-with').hide();
          break;
          case 'Investor':
            $('#webform-component-company').show();
            $('#webform-component-application').hide();
            $('#webform-component-are-you-working-with').hide();
            $('#webform-component-name-of-company-you-are-working-with').hide();
          break;
          case 'Media':
            $('#webform-component-company').show();
            $('#edit-submitted-company').removeAttr('disabled').rules('add', {
              required: true
            });
            $('#webform-component-application').hide();
            $('#webform-component-are-you-working-with').hide();
            $('#webform-component-name-of-company-you-are-working-with').hide();
          break;
          case "Product Designer":
          case "Manufacturer":
            $('#webform-component-company').show();
            $('#edit-submitted-company').removeAttr('disabled').rules('add', {
              required: true
            });
            $('#webform-component-application').show();
            $('#webform-component-are-you-working-with').show();
            $('#webform-component-name-of-company-you-are-working-with').show();
          break;
          case "Researcher":
            $('#webform-component-company').show();
            $('#edit-submitted-company').removeAttr('disabled');
            $('#webform-component-application').show();
            $('#webform-component-are-you-working-with').show();
            $('#webform-component-name-of-company-you-are-working-with').show();
          break;
          case "Other":
            $('#webform-component-company').hide();
            $('#edit-submitted-company').rules("remove");
            $('#webform-component-application').hide();
            $('#webform-component-are-you-working-with').hide();
            $('#webform-component-name-of-company-you-are-working-with').hide();
          break;
        }
      });
      $("#webform-component-are-you-working-with input").change(function () {
        if($("#webform-component-are-you-working-with input:checked").size() === 0) {
          $('#webform-component-name-of-company-you-are-working-with input').rules('remove');
          $('#webform-component-name-of-company-you-are-working-with .form-required').remove();
        }
        else {
          $('#webform-component-name-of-company-you-are-working-with input').rules('add', {
            required: true
          });
          if($('#webform-component-name-of-company-you-are-working-with .form-required').size() === 0) {
            $('#webform-component-name-of-company-you-are-working-with label').append('<span class="form-required">*</span>');
          }
        }
      });
    }
  });

}

